class Solution {
public:
    int sumOfFlooredPairs(vector<int>& nums) {
        const int MOD = 1000000007;
        int maxVal = 0;
        for (int x : nums) maxVal = max(maxVal, x);
        vector<int> cnt(maxVal + 1, 0);
        for (int x : nums) cnt[x]++;
        vector<long long> prefix(maxVal + 2, 0);
        for (int i = 1; i <= maxVal; i++) prefix[i] = prefix[i - 1] + cnt[i];
        prefix[maxVal + 1] = prefix[maxVal];
        long long ans = 0;
        for (int d = 1; d <= maxVal; d++) {
            if (cnt[d] == 0) continue;
            long long cd = cnt[d];
            for (int m = 1; m * d <= maxVal; m++) {
                int lo = m * d;
                int hi = min((m + 1) * d - 1, maxVal);
                long long count = prefix[hi] - prefix[lo - 1];
                ans = (ans + (long long)m * cd % MOD * count % MOD) % MOD;
            }
        }
        return (int)ans;
    }
};
